import { setInterfaceState } from "./gameInterface/interfaceState";

const updatedCustomDurations = { ...Context.interfaceState.state.customDurations }
updatedCustomDurations[Context.action.uid] = +(Context.duration)

setInterfaceState({ customDurations: updatedCustomDurations });

script.content:
import { setInterfaceState } from "./gameInterface/interfaceState";
if (Context.interfaceState.state.customDurations[Context.action.uid] === undefined) {
    const updatedCustomDurations = { ...Context.interfaceState.state.customDurations }
    updatedCustomDurations[Context.action.uid] = Context.action.getSelectOptions().default;

    setInterfaceState({ customDurations: updatedCustomDurations });
}

Context.interfaceState.state.customDurations[Context.action.uid] || '';
